-- FOLD8 (2026-11-19): make the live card_overrides rows match the folded canonical/cards.json.
-- DO NOT RUN until the owner says "apply it". Proposed only (CLAUDE.md hard rule: live writes need "apply it").
-- 173 card rows (every non-deleted, non-__cfg row; the 94 __cfg rows are not touched). One transaction.
-- Each row's data = the folded card from cards.json (art left out: the file's art is inlined and huge; a row's own "art", if it has one, is kept).
-- Rollback: the backup table card_overrides_bak_20261119 made in the same transaction (see the .md beside this file).
-- Note: updated_by is a uuid column, so the text 'fold8' cannot be stored; updated_by is left as it is and updated_at is set to now().
begin;
create table card_overrides_bak_20261119 as select * from card_overrides;
create temp table fold8(id text primary key, card jsonb) on commit drop;
update card_overrides o
   set data = f.card || case when o.data ? 'art' then jsonb_build_object('art', o.data->'art') else '{}'::jsonb end,
       updated_at = now()
  from fold8 f
 where o.id = f.id and not o.deleted;
-- expect 173 rows updated, 267 rows in all, 5 deleted untouched
do $$ begin
  if (select count(*) from card_overrides) <> 267 then raise exception 'row count changed'; end if;
  if (select count(*) from card_overrides o join fold8 f using (id) where o.data - 'art' <> f.card - 'art') <> 0 then raise exception 'rows do not match'; end if;
end $$;
commit;
